package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen1Test {

    private TestableTypeDeserializer sut;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockBaseType;
    private TypeIdResolver mockIdResolver;

    // Since the method is protected, we use a subclass to expose it for testing
    private static class TestableTypeDeserializer extends TypeDeserializerBase {
        private JsonDeserializer<Object> mockDeserializer;
        private JsonDeserializer<Object> mockDefaultDeserializer;
        private boolean reportMappingExceptionCalled = false;

        protected TestableTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) {
            return null;
        }

        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        @Override
        public String baseTypeName() {
            return "test";
        }

        public void setMockDeserializer(JsonDeserializer<Object> deser) {
            this.mockDeserializer = deser;
        }

        public void setMockDefaultDeserializer(JsonDeserializer<Object> deser) {
            this.mockDefaultDeserializer = deser;
        }

        public void setReportMappingExceptionCalled(boolean called) {
            this.reportMappingExceptionCalled = called;
        }

        @Override
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return mockDeserializer;
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return mockDefaultDeserializer;
        }

        // Expose protected method for testing
        @Override
        public Object _deserializeWithNativeTypeId(JsonParser jp, DeserializationContext ctxt, Object typeId) throws IOException {
            return super._deserializeWithNativeTypeId(jp, ctxt, typeId);
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBaseType = mock(JavaType.class);
        mockIdResolver = mock(TypeIdResolver.class);
        sut = new TestableTypeDeserializer(mockBaseType, mockIdResolver, "type", true, null);
    }

    @Test
    public void testTypeIdIsNull_And_DefaultDeserializerFound() throws IOException {
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        sut.setMockDefaultDeserializer(mockDeser);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals(expectedResult, result);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void testTypeIdIsNull_And_DefaultDeserializerNotFound() throws IOException {
        sut.setMockDefaultDeserializer(null);

        // Mocking context to handle reportMappingException
        doAnswer(invocation -> {
            sut.setReportMappingExceptionCalled(true);
            return null;
        }).when(mockContext).reportMappingException(any(String.class));

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertNull(result);
        verify(mockContext).reportMappingException(contains("No (native) type id found"));
    }

    @Test
    public void testTypeIdIsString() throws IOException {
        String typeId = "myType";
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        sut.setMockDeserializer(mockDeser);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        // Verify _findDeserializer was called with the string
        verify(sut)._findDeserializer(mockContext, typeId);
    }

    @Test
    public void testTypeIdIsNotString_ButIsObject() throws IOException {
        Integer typeId = 123;
        String expectedTypeIdStr = "123";
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        sut.setMockDeserializer(mockDeser);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        verify(sut)._findDeserializer(mockContext, expectedTypeIdStr);
    }
}
